-- Göstermelik (demo) cihazlar. Tekrar çalıştırılabilir: aynı adlı cihaz varsa eklenmez.
-- Kaldırmak için: db/demo-remove.sql
SET search_path = demosale;
INSERT INTO devices (name, price, battery_health, grade, warranty, category, stock, description, image_urls, created_at)
SELECT v.name, v.price, v.bh, v.grade, v.warranty, v.category, v.stock, v.descr, v.imgs, now() - (v.age || ' days')::interval
FROM (VALUES
  ('iPhone 15 Pro 256 GB Natürel Titanyum', 54999, 96, 'A', 'Ekim 2026''ya kadar', 'iPhone', 3, 'Mağaza teşhirinden. Ekranda koruyucu film, kasada iz yok. Orijinal kutusu ve USB-C kablosu ile.', ARRAY['https://images.unsplash.com/photo-1678685888221-cda773a3dcdb?auto=format&fit=crop&w=1200&q=75', 'https://images.unsplash.com/photo-1632661674596-df8be070a5c5?auto=format&fit=crop&w=1200&q=75'], 1),
