  ('MacBook Air 13" M3 16 GB / 512 GB Gece Yarısı', 48999, 99, 'A', 'Aralık 2026''ya kadar', 'Mac', 2, 'Teşhir masasından. 12 şarj döngüsü. Klavye ve ekran kusursuz, kutulu.', ARRAY['https://images.unsplash.com/photo-1611186871348-b1ce696e52c9?auto=format&fit=crop&w=1200&q=75', 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=1200&q=75'], 1),
  ('MacBook Pro 14" M3 Pro 18 GB / 1 TB', 79999, 95, 'A', 'Eylül 2026''ya kadar', 'Mac', 1, 'Profesyonel iş akışları için. Uzay Siyahı, 70 W adaptör dahil.', ARRAY['https://images.unsplash.com/photo-1541807084-5c52b6b3adef?auto=format&fit=crop&w=1200&q=75'], 3),
  ('MacBook Air 13" M2 8 GB / 256 GB Yıldız Işığı', 32999, 90, 'B', 'Nisan 2026''ya kadar', 'Mac', 3, 'Alt kasada hafif çizikler. Pil ve performans çok iyi durumda.', ARRAY['https://images.unsplash.com/photo-1496181133206-80ce9b88a853?auto=format&fit=crop&w=1200&q=75'], 9),
