  ('iPad (10. nesil) 64 GB Sarı', 13999, 86, 'C', 'Garanti sona erdi', 'iPad', 1, 'Köşelerde kullanım izleri var, ekran temiz. Okul ve ev kullanımı için uygun.', ARRAY['https://images.unsplash.com/photo-1585790050230-5dd28404ccb9?auto=format&fit=crop&w=1200&q=75'], 15),
