  ('Apple Watch Ultra 2 49 mm Titanyum', 29999, 97, 'A', 'Kasım 2026''ya kadar', 'Apple Watch', 0, 'Okyanus Kordonu ile. Tükendi.', ARRAY['https://images.unsplash.com/photo-1579586337278-3befd40fd17a?auto=format&fit=crop&w=1200&q=75'], 11),
  ('AirPods Pro (2. nesil) USB-C', 7999, 100, 'A', 'Aralık 2026''ya kadar', 'AirPods', 6, 'Aktif gürültü engelleme, MagSafe şarj kutusu. Hijyenik olarak yenilenmiş kulak uçları.', ARRAY['https://images.unsplash.com/photo-1600294037681-c80b4cb5b434?auto=format&fit=crop&w=1200&q=75'], 1),
  ('AirPods (3. nesil) Lightning', 4499, 87, 'B', 'Şubat 2026''ya kadar', 'AirPods', 3, 'Kutuda hafif kullanım izleri. Ses kalitesi kusursuz.', ARRAY['https://images.unsplash.com/photo-1606220588913-b3aacb4d2f46?auto=format&fit=crop&w=1200&q=75'], 10),
  ('AirPods Max Uzay Grisi', 17999, 93, 'A', 'Temmuz 2026''ya kadar', 'AirPods', 1, 'Smart Case ile. Kulak yastıkları yenilendi.', ARRAY['https://images.unsplash.com/photo-1625842268584-8f3296236761?auto=format&fit=crop&w=1200&q=75'], 7),
  ('Magic Keyboard (Touch ID) Türkçe Q', 3499, 100, 'A', 'Ekim 2026''ya kadar', 'Aksesuar', 5, 'Touch ID''li kablosuz klavye, Apple silikonlu Mac''lerle uyumlu.', ARRAY['https://images.unsplash.com/photo-1583394838336-acd977736f90?auto=format&fit=crop&w=1200&q=75'], 3),
  ('MagSafe Şarj Aleti 1 m', 899, 100, 'A', 'Kasım 2026''ya kadar', 'Aksesuar', 8, 'Teşhirde kullanılmış, tamamen işlevsel.', ARRAY['https://images.unsplash.com/photo-1609081219090-a6d81d3085bf?auto=format&fit=crop&w=1200&q=75'], 14),
  ('Apple Pencil (USB-C)', 1999, 100, 'B', 'Haziran 2026''ya kadar', 'Aksesuar', 2, 'Gövdede hafif iz. Uç değiştirildi.', ARRAY['https://images.unsplash.com/photo-1591337676887-a217a6970a8a?auto=format&fit=crop&w=1200&q=75'], 18)
) AS v(name, price, bh, grade, warranty, category, stock, descr, imgs, age)
WHERE NOT EXISTS (SELECT 1 FROM devices d WHERE d.name = v.name);
